func TestPvPokeOracleBuzzwoleVersusOinkologne(t *testing.T) {
	buzzwole := Fighter{
		ID: "buzzwole", Name: "Buzzwole", Types: []string{"bug", "fighting"},
		Attack: 129.86588145, Defense: 109.17012345, HP: 119,
		FastMove: Move{
			ID: "POISON_JAB", Name: "Poison Jab", Type: "poison",
			Kind: FastMove, Power: 7, EnergyGain: 7, Turns: 2,
		},
		ChargedMoves: []Move{
			{
				ID: "POWER_UP_PUNCH", Name: "Power-Up Punch", Type: "fighting",
				Kind: ChargedMove, Power: 20, EnergyCost: 35, Turns: 1,
				Buff: BuffEffect{AttackerAttack: 1, Chance: 1},
			},
			{
				ID: "SUPER_POWER", Name: "Superpower", Type: "fighting",
				Kind: ChargedMove, Power: 85, EnergyCost: 40, Turns: 1,
				Buff: BuffEffect{AttackerAttack: -1, AttackerDefense: -1, Chance: 1},
			},
		},
	}
	oinkologne := Fighter{
		ID: "oinkologne_female", Name: "Oinkologne (Female)", Types: []string{"normal"},
		Attack: 112.6369432, Defense: 108.3518421, HP: 162,
		FastMove: Move{
			ID: "MUD_SLAP", Name: "Mud Slap", Type: "ground",
			Kind: FastMove, Power: 11, EnergyGain: 10, Turns: 3,
		},
		ChargedMoves: []Move{
			{
				ID: "BODY_SLAM", Name: "Body Slam", Type: "normal",
				Kind: ChargedMove, Power: 55, EnergyCost: 35, Turns: 1,
			},
			{
				ID: "TRAILBLAZE", Name: "Trailblaze", Type: "grass",
				Kind: ChargedMove, Power: 65, EnergyCost: 45, Turns: 1,
				Buff: BuffEffect{AttackerAttack: 1, Chance: 1},
			},
		},
	}
	want := [3][3]int{
		{915, 314, 200},
		{915, 659, 575},
		{915, 844, 575},
	}
	assertPvPokeScoreGrid(t, buzzwole, oinkologne, want)
}

