func TestPvPokeOracleDefersSelfDebuffForBestOpponentMove(t *testing.T) {
	pangoro := Fighter{
		ID: "pangoro", Name: "Pangoro", Types: []string{"fighting", "dark"},
		Attack: 136.5878345, Defense: 91.24747450000001, HP: 130,
		FastMove: Move{
			ID: "KARATE_CHOP", Name: "Karate Chop", Type: "fighting",
			Kind: FastMove, Power: 5, EnergyGain: 9, Turns: 2,
		},
		ChargedMoves: []Move{
			{
				ID: "CLOSE_COMBAT", Name: "Close Combat", Type: "fighting",
				Kind: ChargedMove, Power: 100, EnergyCost: 45, Turns: 1,
				Buff: BuffEffect{AttackerDefense: -2, Chance: 1},
			},
			{
				ID: "NIGHT_SLASH", Name: "Night Slash", Type: "dark",
				Kind: ChargedMove, Power: 50, EnergyCost: 35, Turns: 1,
				Buff: BuffEffect{AttackerAttack: 1, Chance: 0.125},
			},
		},
	}
	lickitung := Fighter{
		ID: "lickitung", Name: "Lickitung", Types: []string{"normal"},
		Attack: 99.97439815499999, Defense: 123.54559771999999, HP: 180,
		FastMove: Move{
			ID: "LICK", Name: "Lick", Type: "ghost",
			Kind: FastMove, Power: 3, EnergyGain: 3, Turns: 1,
		},
		ChargedMoves: []Move{
			{
				ID: "BODY_SLAM", Name: "Body Slam", Type: "normal",
				Kind: ChargedMove, Power: 55, EnergyCost: 35, Turns: 1,
			},
			{
				ID: "POWER_WHIP", Name: "Power Whip", Type: "grass",
				Kind: ChargedMove, Power: 90, EnergyCost: 50, Turns: 1,
			},
		},
	}
	result := simulatePvPokeCell(t, pangoro, lickitung, 0, 0)
	if result.Rating(0) != 715 || result.Fighters[0].HP != 56 ||
		result.Fighters[1].HP != 0 || result.Winner != 0 {
		t.Fatalf(
			"Pangoro vs Lickitung result = score %d, hp %d/%d, winner %d; want 715, 56/0, winner 0",
			result.Rating(0),
			result.Fighters[0].HP,
			result.Fighters[1].HP,
			result.Winner,
		)
	}
}

func TestPvPokeOracleSelfDebuffDeferWinnerFlip(t *testing.T) {
	moltres := Fighter{
		ID: "moltres_galarian", Name: "Moltres (Galarian)", Types: []string{"dark", "flying"},
		Attack: 152.01780279000002, Defense: 172.33354602, HP: 155,
		FastMove: Move{
			ID: "SUCKER_PUNCH", Name: "Sucker Punch", Type: "dark",
			Kind: FastMove, Power: 8, EnergyGain: 7, Turns: 2,
		},
		ChargedMoves: []Move{
			{
				ID: "FLY", Name: "Fly", Type: "flying",
				Kind: ChargedMove, Power: 80, EnergyCost: 45, Turns: 1,
			},
			{
				ID: "BRAVE_BIRD", Name: "Brave Bird", Type: "flying",
				Kind: ChargedMove, Power: 130, EnergyCost: 55, Turns: 1,
				Buff: BuffEffect{AttackerDefense: -3, Chance: 1},
			},
		},
	}
	dondozo := Fighter{
		ID: "dondozo", Name: "Dondozo", Types: []string{"water"},
		Attack: 137.4052281, Defense: 138.8440263, HP: 235,
		FastMove: Move{
			ID: "WATERFALL", Name: "Waterfall", Type: "water",
			Kind: FastMove, Power: 11, EnergyGain: 10, Turns: 3,
		},
		ChargedMoves: []Move{
			{
				ID: "SURF", Name: "Surf", Type: "water",
				Kind: ChargedMove, Power: 75, EnergyCost: 45, Turns: 1,
			},
			{
				ID: "OUTRAGE", Name: "Outrage", Type: "dragon",
				Kind: ChargedMove, Power: 110, EnergyCost: 60, Turns: 1,
			},
		},
	}
	result := simulatePvPokeCell(t, moltres, dondozo, 1, 1)
	if result.Rating(0) != 538 || result.Winner != 0 {
		t.Fatalf(
			"Moltres (Galarian) vs Dondozo result = score %d, winner %d; want 538, winner 0",
			result.Rating(0),
			result.Winner,
		)
	}
}

func simulatePvPokeCell(
	t *testing.T,
	focal Fighter,
	opponent Fighter,
	focalShields int,
	opponentShields int,
) BattleResult {
	t.Helper()
	config := DefaultBattleConfig()
	config.Shields = [2]int{focalShields, opponentShields}
	config.RecordTimeline = true
	result, err := Simulate([2]Fighter{focal, opponent}, config)
	if err != nil {
		t.Fatal(err)
	}
	return result
}

func assertPvPokeScoreGrid(
	t *testing.T,
	focal Fighter,
	opponent Fighter,
	want [3][3]int,
) {
	t.Helper()
	for focalShields := 0; focalShields <= 2; focalShields++ {
		for opponentShields := 0; opponentShields <= 2; opponentShields++ {
			result := simulatePvPokeCell(
				t,
				focal,
				opponent,
				focalShields,
				opponentShields,
			)
			if got := result.Rating(0); got != want[focalShields][opponentShields] {
				t.Errorf(
					"%s vs %s shields %d-%d score = %d, want %d; timeline=%#v",
					focal.ID,
					opponent.ID,
					focalShields,
					opponentShields,
					got,
					want[focalShields][opponentShields],
					result.Timeline,
				)
			}
		}
	}
}
